frappe.ui.form.on("New And Existing Product Analysis Module", {

    setup(frm) {
        set_organization_filter(frm);
    },

    onload(frm) {
        set_organization_filter(frm);
        calculate_next_analysis_date(frm);
    },

    refresh(frm) {
        set_organization_filter(frm);
        calculate_next_analysis_date(frm);

        // Existing rows
        if (frm.doc.section_wise_production_capacity) {
            frm.doc.section_wise_production_capacity.forEach(row => {
                set_child_field_permissions(frm, row);
            });
        }
    },

    organization_type(frm) {
        frm.set_value("organization_name", "");
        set_organization_filter(frm);
    },

    date(frm) {
        calculate_next_analysis_date(frm);
    },

    section_wise_production_capacity_add(frm, cdt, cdn) {
        setTimeout(() => {
            let row = locals[cdt][cdn];

            if (row) {
                set_child_field_permissions(frm, row);
            }
        }, 100);
    }

});


/* =========================================================
   ORGANIZATION FILTER
   ========================================================= */

function set_organization_filter(frm) {

    frm.set_query("organization_name", function() {

        let filters = {};

        if (frm.doc.organization_type === "Prospect") {

            filters.custom_status = "Prospect";

        } else if (frm.doc.organization_type === "Customer") {

            filters.custom_status = "Customer";

        } else if (frm.doc.organization_type === "All") {

            filters = {};
        }

        return {
            filters: filters
        };
    });
}


/* =========================================================
   NEXT ANALYSIS DATE
   DATE + 6 MONTHS
   ========================================================= */

function calculate_next_analysis_date(frm) {

    if (!frm.doc.date) {
        return;
    }

    let next_date = frappe.datetime.add_months(
        frm.doc.date,
        6
    );

    frm.set_value(
        "next_analysis_date",
        next_date
    );
}

