frappe.ui.form.on("Section Wise Production Capacity", {

    form_render(frm, cdt, cdn) {
        apply_row_permissions(frm, cdt, cdn);
    },

    output_type(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        if (row.output_type === "Kg") {

            frappe.model.set_value(cdt, cdn, "vial_strength", null);
            frappe.model.set_value(cdt, cdn, "vial_strength_uom", null);
            frappe.model.set_value(cdt, cdn, "vial_monthly_output_quantity", null);

        }

        else if (row.output_type === "Vial") {

            frappe.model.set_value(cdt, cdn, "monthly_output_kg", 0);
        }

        apply_row_permissions(frm, cdt, cdn);
        calculate_vial_to_kg(cdt, cdn);
    },

    vial_strength(frm, cdt, cdn) {
        calculate_vial_to_kg(cdt, cdn);
    },

    vial_strength_uom(frm, cdt, cdn) {
        calculate_vial_to_kg(cdt, cdn);
    },

    vial_monthly_output_quantity(frm, cdt, cdn) {
        calculate_vial_to_kg(cdt, cdn);
    }
});


function apply_row_permissions(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row) {
        return;
    }

    let grid_row = frm.fields_dict
        .section_wise_production_capacity
        .grid
        .get_row(row.name);

    if (!grid_row) {
        return;
    }

    if (row.output_type === "Kg") {

        // KG editable
        grid_row.toggle_editable(
            "monthly_output_kg",
            true
        );

        // Vial fields locked
        grid_row.toggle_editable(
            "vial_strength",
            false
        );

        grid_row.toggle_editable(
            "vial_strength_uom",
            false
        );

        grid_row.toggle_editable(
            "vial_monthly_output_quantity",
            false
        );

    }

    else if (row.output_type === "Vial") {

        // KG locked
        grid_row.toggle_editable(
            "monthly_output_kg",
            false
        );

        // Vial fields editable
        grid_row.toggle_editable(
            "vial_strength",
            true
        );

        grid_row.toggle_editable(
            "vial_strength_uom",
            true
        );

        grid_row.toggle_editable(
            "vial_monthly_output_quantity",
            true
        );
    }
}


function calculate_vial_to_kg(cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row || row.output_type !== "Vial") {
        return;
    }

    let strength = flt(row.vial_strength);
    let quantity = flt(row.vial_monthly_output_quantity);
    let uom = row.vial_strength_uom;

    if (!strength || !quantity || !uom) {

        frappe.model.set_value(
            cdt,
            cdn,
            "monthly_output_kg",
            0
        );

        return;
    }

    let total_kg = 0;

    if (uom === "mg") {

        total_kg = (strength * quantity) / 1000000;

    } else if (uom === "g") {

        total_kg = (strength * quantity) / 1000;

    }

    frappe.model.set_value(
        cdt,
        cdn,
        "monthly_output_kg",
        total_kg
    );
}

