frappe.listview_settings["CRM Prospect Item Conversion Status"] = {

    onload(listview) {

        listview.page.add_inner_button(
            __("Merge Prospect Items"),
            function () {

                merge_prospect_items(listview);

            }
        );

    }

};


function merge_prospect_items(listview) {

    // ------------------------------------------------
    // Get selected records
    // ------------------------------------------------

    const selected = listview.get_checked_items();


    // ------------------------------------------------
    // Minimum 2 records
    // ------------------------------------------------

    if (!selected || selected.length < 2) {

        frappe.msgprint({

            title: __("Cannot Merge"),

            message: __(
                "Please select at least 2 Prospect Items."
            ),

            indicator: "orange"

        });

        return;
    }


    // ------------------------------------------------
    // Get complete records from server
    // ------------------------------------------------

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "CRM Prospect Item Conversion Status",

            filters: {
                name: ["in", selected.map(row => row.name)]
            },

            fields: [
                "name",
                "product_name",
                "prospect_item_name",
                "product_type",
                "status"
            ],

            limit_page_length: selected.length

        },

        freeze: true,

        freeze_message: __(
            "Checking selected Prospect Items..."
        ),

        callback(r) {

            if (r.exc) {
                return;
            }


            const records = r.message || [];


            if (records.length < 2) {

                frappe.msgprint({

                    title: __("Error"),

                    message: __(
                        "Unable to load the selected Prospect Items."
                    ),

                    indicator: "red"

                });

                return;
            }


            // ------------------------------------------------
            // Validate Product Type
            // SELECTED RECORDS MUST BE PROSPECT ITEM
            // ------------------------------------------------

            const invalid_type = records.filter(row => {

                return row.product_type !== "Prospect Item";

            });


            if (invalid_type.length) {

                frappe.msgprint({

                    title: __("Cannot Merge"),

                    message: __(
                        "Only records having Product Type = Prospect Item can be merged."
                    ),

                    indicator: "red"

                });

                return;
            }


            // ------------------------------------------------
            // Validate Status
            // SELECTED RECORDS MUST BE ACTIVE
            // ------------------------------------------------

            const invalid_status = records.filter(row => {

                return row.status !== "Active";

            });


            if (invalid_status.length) {

                frappe.msgprint({

                    title: __("Cannot Merge"),

                    message: __(
                        "Only Active Prospect Items can be merged."
                    ),

                    indicator: "red"

                });

                return;
            }


            // ------------------------------------------------
            // Get ACTIVE Prospect + Existing Items
            // FOR MASTER SELECTION ONLY
            // ------------------------------------------------

            frappe.call({

                method: "frappe.client.get_list",

                args: {

                    doctype: "CRM Prospect Item Conversion Status",

                    filters: [
                        ["status", "=", "Active"],
                        [
                            "product_type",
                            "in",
                            ["Prospect Item", "Existing Item"]
                        ]
                    ],

                    fields: [
                        "name",
                        "product_name",
                        "prospect_item_name",
                        "product_type",
                        "status"
                    ],

                    limit_page_length: 0,

                    order_by: "product_name asc"

                },

                callback(master_response) {

                    if (master_response.exc) {
                        return;
                    }


                    const active_master_items =
                        master_response.message || [];


                    // ------------------------------------------------
                    // Create Master Product options
                    //
                    // ACTIVE PROSPECT ITEM
                    // +
                    // ACTIVE EXISTING ITEM
                    // ------------------------------------------------

                    const options = active_master_items.map(row => {

                        return {

                            label:
                                `${row.product_name} [${row.product_type}]`,

                            value: row.name

                        };

                    });


                    // ------------------------------------------------
                    // Master selection dialog
                    // ------------------------------------------------

                    const dialog = new frappe.ui.Dialog({

                        title: __("Merge Prospect Items"),

                        fields: [

                            {

                                fieldname: "master_item",

                                fieldtype: "Select",

                                label: __(
                                    "Select Correct / Master Spelling"
                                ),

                                options: options,

                                reqd: 1

                            }

                        ],

                        primary_action_label: __("Merge"),

                        primary_action(values) {


                            // ------------------------------------------------
                            // Validate master selection
                            // ------------------------------------------------

                            if (!values.master_item) {

                                frappe.msgprint({

                                    title: __("Required"),

                                    message: __(
                                        "Please select which spelling should remain Active."
                                    ),

                                    indicator: "orange"

                                });

                                return;
                            }


                            // ------------------------------------------------
                            // Find selected Master
                            // ------------------------------------------------

                            const master =
                                active_master_items.find(row => {

                                    return row.name === values.master_item;

                                });


                            if (!master) {

                                frappe.msgprint({

                                    title: __("Error"),

                                    message: __(
                                        "Invalid Master Product selected."
                                    ),

                                    indicator: "red"

                                });

                                return;
                            }


                            // ------------------------------------------------
                            // Find duplicate Prospect Items
                            //
                            // IMPORTANT:
                            // Only selected Prospect Items will be
                            // sent for conversion.
                            //
                            // Existing Item will NOT be converted.
                            // ------------------------------------------------

                           // ------------------------------------------------
// Selected Prospect Items
// ------------------------------------------------

const prospect_items = records
    .filter(row => row.product_type === "Prospect Item");


// ------------------------------------------------
// If Master is Existing Item
// ------------------------------------------------

const is_existing_master =
    master.product_type === "Existing Item";


// ------------------------------------------------
// Duplicate Prospect Items
// ------------------------------------------------

const duplicate_items = prospect_items
    .filter(row => {

        // If Existing Item is master,
        // all selected Prospect Items are converted

        if (is_existing_master) {
            return true;
        }

        // If Prospect Item is master,
        // all other selected Prospect Items are converted

        return row.name !== master.name;

    })
    .map(row => row.name);

                            // ------------------------------------------------
                            // Confirmation
                            // ------------------------------------------------

                            frappe.confirm(

                                __(
                                    "Keep <b>{0}</b> as Active and mark the other {1} selected Prospect Items as Converted?",
                                    [
                                        master.product_name,
                                        duplicate_items.length
                                    ]
                                ),

                                function () {


                                    // ------------------------------------------------
                                    // Call server method
                                    // ------------------------------------------------

                                    frappe.call({

                                        method: "merge_prospect_items",

                                        args: {

                                            master_item: master.name,

                                            duplicate_items:
                                                duplicate_items

                                        },

                                        freeze: true,

                                        freeze_message: __(
                                            "Updating Prospect Items..."
                                        ),

                                        callback(r) {

                                            if (r.exc) {
                                                return;
                                            }


                                            dialog.hide();


                                            frappe.show_alert({

                                                message: __(
                                                    "Master spelling kept Active. Other selected Prospect Items marked as Converted."
                                                ),

                                                indicator: "green"

                                            });


                                            listview.refresh();

                                        }

                                    });

                                }

                            );

                        }

                    });


                    // ------------------------------------------------
                    // SHOW DIALOG
                    // ------------------------------------------------

                    dialog.show();

                }

            });

        }

    });

}

