    if (!html_field) {

        console.error(
            "HTML field custom_dashboard_html not found."
        );

        return;
    }

    const wrapper = $(html_field.$wrapper || html_field.wrapper);

    if (!wrapper.length) {
        return;
    }


    /* =====================================================
       DASHBOARD HTML
    ===================================================== */

    const html = `

        <div class="product-analysis-container"
             style="
                width:100%;
                padding:10px 0 20px 0;
             ">

            <!-- HEADER -->

            <div style="
                display:flex;
                justify-content:space-between;
                align-items:center;
                gap:10px;
                margin-bottom:15px;
                flex-wrap:wrap;
            ">

                <div>

                    <h4 style="
                        margin:0;
                        font-weight:600;
                    ">
                        ${__("Product Analysis")}
                    </h4>

                    <div class="text-muted"
                         style="
                            margin-top:4px;
                            font-size:13px;
                         ">
                        ${__(
                            "Product analysis records for this organization."
                        )}
                    </div>

                </div>


                <!-- NEW BUTTON -->

                <button
                    type="button"
                    class="btn btn-primary btn-sm new-product-analysis-btn"
                >

                    <i class="fa fa-plus"></i>

                    ${__("New Product Analysis")}

                </button>

            </div>


            <!-- ORGANIZATION -->

            <div style="
                padding:10px 12px;
                margin-bottom:15px;
                background:var(--subtle-fg);
                border:1px solid var(--border-color);
                border-radius:6px;
            ">

                <span class="text-muted">
                    ${__("Organization")}:
                </span>

                <strong>
                    ${frappe.utils.escape_html(frm.doc.name || "")}
                </strong>

            </div>


            <!-- EXISTING PRODUCT ANALYSIS -->

            <div style="
                display:flex;
                justify-content:space-between;
                align-items:center;
                margin-bottom:10px;
            ">

                <div style="
                    font-weight:600;
                    font-size:15px;
                ">
                    ${__("Existing Product Analysis")}
                </div>

                <span
                    class="badge badge-primary product-analysis-count"
                    style="
                        font-size:12px;
                        padding:5px 8px;
                    "
                >
                    0
                </span>

            </div>


            <!-- RECORD LIST -->

            <div class="product-analysis-list">

                <div
                    class="text-muted"
                    style="
                        padding:20px 10px;
                        text-align:center;
                    "
                >
                    ${__("Loading...")}
                </div>

            </div>

        </div>

    `;


    // Render
    wrapper.html(html);


    /* =====================================================
       LOAD EXISTING RECORDS
    ===================================================== */

    load_product_analysis(frm, wrapper);


    /* =====================================================
       NEW PRODUCT ANALYSIS BUTTON
    ===================================================== */

    wrapper
        .find(".new-product-analysis-btn")
        .off("click.product_analysis")
        .on(
            "click.product_analysis",
            function() {

                create_product_analysis(frm);

            }
        );

}


/* =========================================================
   LOAD EXISTING PRODUCT ANALYSIS
========================================================= */

function load_product_analysis(frm, dashboard_wrapper) {

    if (!frm.doc.name) {
        return;
    }


    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype:
                "New And Existing Product Analysis Module",

            filters: [
                [
                    "organization_name",
                    "=",
                    frm.doc.name
                ]
            ],

            fields: [
                "name",
                "date",
                "next_analysis_date",
                "organization_type"
            ],

            order_by: "date desc",

            limit_page_length: 100

        },


        callback: function(r) {

            const list_wrapper =
                dashboard_wrapper.find(
                    ".product-analysis-list"
                );


            const count_wrapper =
                dashboard_wrapper.find(
                    ".product-analysis-count"
                );


            if (!list_wrapper.length) {
                return;
            }


            const records =
                r.message || [];


            /* =================================================
               UPDATE COUNT
            ================================================= */

            if (count_wrapper.length) {

                count_wrapper.text(
                    records.length
                );

            }


            /* =================================================
               CLEAR LOADING
            ================================================= */

            list_wrapper.empty();


            /* =================================================
               NO RECORD
            ================================================= */

            if (!records.length) {

                list_wrapper.html(`

                    <div style="
                        padding:25px 15px;
                        text-align:center;
                        border:1px dashed var(--border-color);
                        border-radius:7px;
                        color:var(--text-muted);
                    ">

                        ${__(
                            "No Product Analysis found for this organization."
                        )}

                    </div>

                `);

                return;
            }


            /* =================================================
               TABLE
            ================================================= */

            let table = `

                <div style="
                    width:100%;
                    overflow-x:auto;
                ">

                    <table
                        class="table table-bordered table-hover"
                        style="
                            width:100%;
                            min-width:650px;
                            margin-bottom:0;
                        "
                    >

                        <thead>

                            <tr>

                                <th>
                                    ${__("Analysis")}
                                </th>

                                <th>
                                    ${__("Date")}
                                </th>

                                <th>
                                    ${__("Next Analysis")}
                                </th>

                                <th>
                                    ${__("Organization Type")}
                                </th>

                            </tr>

                        </thead>

                        <tbody>
            `;


            /* =================================================
               RECORDS
            ================================================= */

            records.forEach(function(row) {

                const analysis_name =
                    frappe.utils.escape_html(
                        row.name || ""
                    );


                const date =
                    row.date
                        ? frappe.datetime.str_to_user(
                            row.date
                        )
                        : "-";


                const next_date =
                    row.next_analysis_date
                        ? frappe.datetime.str_to_user(
                            row.next_analysis_date
                        )
                        : "-";


                const organization_type =
                    frappe.utils.escape_html(
                        row.organization_type || "-"
                    );


                table += `

                    <tr>

                        <td>

                            <a
                                href="#"
                                class="product-analysis-link"
                                data-name="${encodeURIComponent(
                                    row.name || ""
                                )}"
                            >
                                ${analysis_name}
                            </a>

                        </td>


                        <td>
                            ${date}
                        </td>


                        <td>
                            ${next_date}
                        </td>


                        <td>
                            ${organization_type}
                        </td>

                    </tr>

                `;

            });


            table += `

                        </tbody>

                    </table>

                </div>

            `;


            list_wrapper.html(table);


            /* =================================================
               OPEN EXISTING RECORD
            ================================================= */

            list_wrapper
                .find(".product-analysis-link")
                .off("click.product_analysis")
                .on(
                    "click.product_analysis",
                    function(e) {

                        e.preventDefault();

                        const name =
                            decodeURIComponent(
                                $(this).attr(
                                    "data-name"
                                )
                            );


                        frappe.set_route(
                            "Form",
                            "New And Existing Product Analysis Module",
                            name
                        );

                    }
                );

        },


        error: function(error) {

            console.error(
                "Product Analysis Error:",
                error
            );


            dashboard_wrapper
                .find(".product-analysis-list")
                .html(`

                    <div
                        class="text-danger"
                        style="padding:15px;"
                    >
                        ${__(
                            "Unable to load Product Analysis."
                        )}
                    </div>

                `);

        }

    });

}


/* =========================================================
   CREATE NEW PRODUCT ANALYSIS
========================================================= */

function create_product_analysis(frm) {

    if (!frm.doc.name) {

        frappe.msgprint(
            __(
                "Please save the Organization first."
            )
        );

        return;
    }


    /* =====================================================
       GET ORGANIZATION STATUS
    ===================================================== */

    let organization_type =
        frm.doc.custom_status || "Prospect";


    organization_type =
        organization_type.trim();


    /* =====================================================
       OPEN NEW FORM
    ===================================================== */

    frappe.new_doc(
        "New And Existing Product Analysis Module",
        {

            // Auto populate Organization
            organization_name:
                frm.doc.name,

            // Auto populate Organization Type
            organization_type:
                organization_type

        }
    );

}

