// ==========================================================
// WHEN GRID ROW IS RENDERED
// This is important in Frappe CRM
// ==========================================================

$(document).on(
    'grid-row-render',
    function (e, grid_row) {

        if (!grid_row) {
            return;
        }

        if (!grid_row.doc) {
            return;
        }

        if (
            grid_row.doc.parentfield !==
            'item_wise_production_capacity'
        ) {
            return;
        }

        let frm = cur_frm;

        if (!frm) {
            return;
        }

        apply_month_rule_to_grid_row(
            frm,
            grid_row
        );

    }
);


// ==========================================================
// APPLY TO ALL EXISTING ROWS
// ==========================================================

function apply_all_month_rules(frm) {

    if (
        !frm.fields_dict.item_wise_production_capacity
    ) {
        return;
    }

    let rows =
        frm.doc.item_wise_production_capacity || [];

    rows.forEach(function (row) {

        apply_month_rule(
            frm,
            row.doctype,
            row.name
        );

    });

}


// ==========================================================
// APPLY RULE TO ONE ROW
// ==========================================================

function apply_month_rule(
    frm,
    cdt,
    cdn
) {

    let row = locals[cdt] &&
              locals[cdt][cdn];

    if (!row) {
        return;
    }

    let is_once_a_year =
        row.periodicity === 'Once a Year';


    // ======================================================
    // OTHER PERIODICITY
    // Clear Month
    // ======================================================

    if (!is_once_a_year) {

        if (row.month) {

            frappe.model.set_value(
                cdt,
                cdn,
                'month',
                ''
            );

        }

    }


    // ======================================================
    // WAIT FOR GRID
    // ======================================================

    setTimeout(function () {

        let table =
            frm.fields_dict
                .item_wise_production_capacity;

        if (!table || !table.grid) {
            return;
        }

        let grid_row =
            table.grid.get_row(cdn);

        if (!grid_row) {
            return;
        }

        apply_month_rule_to_grid_row(
            frm,
            grid_row
        );

    }, 100);

}


// ==========================================================
// ACTUAL MONTH FIELD CONTROL
// ==========================================================

function apply_month_rule_to_grid_row(
    frm,
    grid_row
) {

    if (!grid_row.doc) {
        return;
    }

    let row = grid_row.doc;

    let editable =
        row.periodicity === 'Once a Year';


    // ======================================================
    // Frappe Grid editable control
    // ======================================================

    if (typeof grid_row.toggle_editable === 'function') {

        grid_row.toggle_editable(
            'month',
            editable
        );

    }


    // ======================================================
    // Direct field control
    // ======================================================

    if (
        grid_row.on_grid_fields_dict &&
        grid_row.on_grid_fields_dict.month
    ) {

        let field =
            grid_row.on_grid_fields_dict.month;

        field.df.read_only =
            editable ? 0 : 1;

        field.refresh();

    }


    // ======================================================
    // DOM CONTROL
    // Important for CRM editable grid
    // ======================================================

    let row_element =
        $(grid_row.row);

    let month_wrapper =
        row_element.find(
            '[data-fieldname="month"]'
        );

    if (!month_wrapper.length) {
        return;
    }


    // Select/input inside Month field
    month_wrapper
        .find('input, select, textarea')
        .prop(
            'disabled',
            !editable
        );


    // Frappe input controls
    if (editable) {

        month_wrapper
            .removeClass('disabled');

    } else {

        month_wrapper
            .addClass('disabled');

    }

}
